static inline int
_os_atomic_mo_has_acquire( memory_order ord)
{
 switch (ord) {
 case memory_order_consume:
 case memory_order_acquire:
 case memory_order_acq_rel:
 case memory_order_seq_cst:
  return 1;
 default:
  return 0;
 }
}

static inline int
_os_atomic_mo_has_release( memory_order ord)
{
 switch (ord) {
 case memory_order_release:
 case memory_order_acq_rel:
 case memory_order_seq_cst:
  return 1;
 default:
  return 0;
 }
}
